import{d as s,C as i,o as g,c as h,E as n,a3 as a}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"节卦","description":"水泽节","frontmatter":{"title":"节卦","description":"水泽节","category":"hexagram","aliases":["节","水泽节"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-60.md","filePath":"yijing/hexagrams/hexagram-60.md","lastUpdated":1787800334000}'),m={name:"yijing/hexagrams/hexagram-60.md"},b=s({...m,setup(p){const o=[{id:"huting",term:"不出户庭",pinyin:"bù chū hù tíng",meaning:"连内门都不出。户为内门，庭为堂前院子；喻时机未通、守在内里。",context:"初九知通塞——塞则守，通则出。"},{id:"menting",term:"不出门庭",pinyin:"bù chū mén tíng",meaning:"已走到大门口却还不出。门庭为家门内外之交；喻时机已到却裹足不前。",context:"九二失时极——通了却不出，是另一种失节。"},{id:"bujieruo",term:"不节若",pinyin:"bù jié ruò",meaning:"不节制的样子。「若」为语助词，表「……的样子」。"},{id:"jieruo",term:"嗟若",pinyin:"jiē ruò",meaning:"叹息、嗟叹的样子。",context:"六三失节后的那一声叹气。"},{id:"anjie",term:"安节",pinyin:"ān jié",meaning:"安然而受、不费力气的节制。",context:"六四承上道——接上的，不是撑出来的。"},{id:"ganjie",term:"甘节",pinyin:"gān jié",meaning:"甘之如饴、发自内心喜悦的节制。",context:"九五居中得正，节成了生活方式。"},{id:"kujie",term:"苦节",pinyin:"kǔ jié",meaning:"苦苦硬撑、勉强压抑的节制。",context:"苦节不可贞——强迫出来的节制走不远。"},{id:"zhitongsai",term:"知通塞",pinyin:"zhī tōng sè",meaning:"知道通与不通，判断时机的开合。",context:"初九不出户庭，正是知通塞。"},{id:"shishiji",term:"失时极",pinyin:"shī shí jí",meaning:"错过时机的极点。",context:"九二时机已到却不出，失时到了极点。"},{id:"chengshangdao",term:"承上道",pinyin:"chéng shàng dào",meaning:"承顺上面的道；六四顺承九五。",context:"安节之亨，在于接上了上面的节。"},{id:"juweizhong",term:"居位中",pinyin:"jū wèi zhōng",meaning:"居于中正之位；九五居中得正。"},{id:"daogiong",term:"道穷",pinyin:"dào qióng",meaning:"道走到尽头、无路可走。",context:"苦节贞凶，其道穷也。"},{id:"huiwang",term:"悔亡"}],e=[{position:"初九",type:"yang",text:"不出户庭，无咎。",xiang:"不出户庭，知通塞也。",textModern:"连内门都不出，无咎——知道此时外面不通，所以守在内里。",xiangModern:"不出户庭，是因为知道通塞：塞则守，通则出。"},{position:"九二",type:"yang",text:"不出门庭，凶。",xiang:"不出门庭凶，失时极也。",textModern:"已经走到大门口却还不出，凶。",xiangModern:"不出门庭而凶，是因为错过了时机的极点——通了却不出，是另一种失节。"},{position:"六三",type:"yin",text:"不节若，则嗟若，无咎。",xiang:"不节之嗟，又谁咎也。",textModern:"不节制的样子，于是嗟叹；认了，就无咎。",xiangModern:"自己放纵招来的嗟叹，又能怪谁呢——那一声叹气就是回头的开始。"},{position:"六四",type:"yin",text:"安节，亨。",xiang:"安节之亨，承上道也。",textModern:"安然而受的节制，亨通。",xiangModern:"安节之亨，在于承顺上面的道——接上的，不是撑出来的。"},{position:"九五",type:"yang",text:"甘节，吉，往有尚。",xiang:"甘节之吉，居位中也。",textModern:"甘之如饴的节制，吉；这样往前走，会得到崇尚。",xiangModern:"甘节之吉，在于居中得正——发自内心喜欢这样活。"},{position:"上六",type:"yin",text:"苦节，贞凶，悔亡。",xiang:"苦节贞凶，其道穷也。",textModern:"苦苦硬撑的节制，即使守正也凶；知道苦了肯回头，悔恨可消。",xiangModern:"苦节贞凶，因为这条路已走到尽头——强迫出来的节制走不远。"}];return(u,t)=>{const r=i("DaoHexagramViewer"),l=i("DaoHexagramYaoCards"),d=i("DaoKeywordCards");return g(),h("div",null,[n(r,{name:"节",fullName:"水泽节",upper:"☵",lower:"☱",guaCi:"节，亨。苦节不可贞。",pinyin:["jié"],element:"水",direction:"北",insight:"泽上有水，承而不溢；节是内心的数度，不是外来的枷锁。",guaSlug:"60shuizejie",lines:e}),t[0]||(t[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>泽上有水，节。君子以制数度，议德行。</p><p>泽承着水，水入泽而不溢，正是「节」之象。节不是堵住水，是让水被泽接住、化掉——先承住，才知道节在哪里。</p><ul><li><strong>制数度</strong> —— 制定数量与法度。数度是节的外形：分寸、刻度、规矩。</li><li><strong>议德行</strong> —— 斟酌、讲求德行。德行是节的内神：把度活成自觉。</li></ul><p>从「制数度」到「议德行」，是一条从外在制度回到内心自觉的路：先有数度，把分寸定下来；再议德行，把分寸长进自己身上。</p><p>分形结构：</p><ul><li>制数度（制度）→ 微观：日程、预算、commit 纪律</li><li>议德行（自觉）→ 宏观：把节制活成喜欢的样子</li></ul><p>数度是节之形，德行是节之神。君子先制数度，是为了最终不用数度——内化成德行，节制就成了自然而然。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>节亨，刚柔分而刚得中。苦节不可贞，其道穷也。说以行险，当位以节，中正以通。天地节而四时成。节以制度，不伤财，不害民。</p><p>逐句释义：</p><ul><li><strong>节亨，刚柔分而刚得中</strong> —— 节是亨通的：阴阳刚柔各有分际，阳刚居中得正。有分别，才有度。</li><li><strong>苦节不可贞，其道穷也</strong> —— 苦苦硬撑的节制不可持久，因为这条路已经走到尽头。强迫出来的节制走不远。</li><li><strong>说以行险，当位以节，中正以通</strong> —— 带着喜悦涉入险境（下兑为悦、上坎为险），当位而行节，中正就能通达。节不是压抑，是「说以行险」。</li><li><strong>天地节而四时成</strong> —— 天地有节度，才有四季分明。节是宇宙运行的法则，不是人间的枷锁。</li><li><strong>节以制度，不伤财，不害民</strong> —— 用制度来节：不伤财、不害民。节的目的从来不是压榨，是保全。</li></ul><blockquote><p><strong>说以行险</strong>：节卦的深层结构——下兑（泽）是悦，上坎（水）是险。节不是退避险，是带着喜悦去行险。把节制活成甘，就是「说以行险」。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',14)),n(l,{element:"水",guaSlug:"60shuizejie",glossary:o,items:e}),t[1]||(t[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初九-·-不出户庭-无咎" tabindex="-1">初九 · 不出户庭，无咎 <a class="header-anchor" href="#初九-·-不出户庭-无咎" aria-label="Permalink to &quot;初九 · 不出户庭，无咎&quot;">​</a></h3><ul><li><strong>户庭</strong> → 户是内门，庭是堂前院子。「不出户庭」，是连家门都不出。</li><li>象曰「不出户庭，知通塞也」——知道通与塞。</li></ul><p>解读：初九处节卦之初，上临九二，同阳无应，又见上卦坎险——外面是不通的，所以不出。<strong>知通塞</strong>：每件事单独判断它的节点，不是&quot;永远不出&quot;，是&quot;现在不通所以不出&quot;。</p><blockquote><p>核心洞见：节的第一爻不是教人躲，是教人辨。不出，是因为知道此时出去不通——不出是主动的度，不是胆怯。</p></blockquote><h3 id="九二-·-不出门庭-凶" tabindex="-1">九二 · 不出门庭，凶 <a class="header-anchor" href="#九二-·-不出门庭-凶" aria-label="Permalink to &quot;九二 · 不出门庭，凶&quot;">​</a></h3><ul><li><strong>门庭</strong> → 门是大门，门庭是家门口。九二与初九只差一步：初九在屋内，九二已到门口。</li><li>象曰「不出门庭凶，失时极也」——错过时机的极点。</li></ul><p>解读：九二阳刚居中，上应九五，时机已到，却仍不出。「不出」在初九是度，在九二是怯——<strong>时到了不出，是另一种失节</strong>。</p><blockquote><p>对照：初九之不出是知通塞（不通），九二之不出是失时极（通了却不出）。同一个「不出」，一个守在节点前，一个错过了节点。</p></blockquote><h3 id="六三-·-不节若-则嗟若-无咎" tabindex="-1">六三 · 不节若，则嗟若，无咎 <a class="header-anchor" href="#六三-·-不节若-则嗟若-无咎" aria-label="Permalink to &quot;六三 · 不节若，则嗟若，无咎&quot;">​</a></h3><ul><li><strong>不节若</strong> → 若，「……的样子」；不节制的样子。</li><li><strong>嗟若</strong> → 叹息、嗟叹的样子。</li><li>象曰「不节之嗟，又谁咎也」——自己放纵造成的嗟叹，又能怪谁呢。</li></ul><p>解读：六三阴柔不中不正，管不住自己，于是不节、于是嗟叹。但<strong>那一声叹气就是六三的全部</strong>——嗟叹了、认了，就无咎。</p><blockquote><p>认了，节才接得回来：人不是不会失节，是失节之后有没有那一声「嗟」。</p></blockquote><h3 id="六四-·-安节-亨" tabindex="-1">六四 · 安节，亨 <a class="header-anchor" href="#六四-·-安节-亨" aria-label="Permalink to &quot;六四 · 安节，亨&quot;">​</a></h3><ul><li><strong>安节</strong> → 安然而受的节制。</li><li>象曰「安节之亨，承上道也」——承顺九五之道。</li></ul><p>解读：六四当位，紧承九五，顺理成章地接上节——<strong>是接上的，不是撑出来的</strong>。安节的人不觉得在「忍」，只是刚好接上了。安，是不对抗；承上道，是知道上面有道，安然顺之。</p><h3 id="九五-·-甘节-吉-往有尚" tabindex="-1">九五 · 甘节，吉，往有尚 <a class="header-anchor" href="#九五-·-甘节-吉-往有尚" aria-label="Permalink to &quot;九五 · 甘节，吉，往有尚&quot;">​</a></h3><ul><li><strong>甘节</strong> → 甘之如饴的节制。</li><li>象曰「甘节之吉，居位中也」——居中得正。</li></ul><p>解读：九五居中正之位，节制不是苦的而是甜的——<strong>发自内心喜欢这样活</strong>。甘节是最高的节：不是「我应该」而是「我愿意」。往有尚：这样的节制往前，会得到崇尚。</p><blockquote><p>甘节原型：回头看看自己甘过什么——那些心甘情愿投入、乐在其中的事，就是甘节的活样本。节该长在哪，不是靠苦想，是靠甘过的地方。</p></blockquote><h3 id="上六-·-苦节-贞凶-悔亡" tabindex="-1">上六 · 苦节，贞凶，悔亡 <a class="header-anchor" href="#上六-·-苦节-贞凶-悔亡" aria-label="Permalink to &quot;上六 · 苦节，贞凶，悔亡&quot;">​</a></h3><ul><li><strong>苦节</strong> → 苦苦硬撑的节制。</li><li>象曰「苦节贞凶，其道穷也」——这条路走穷了。</li></ul><p>解读：上六居卦之终，节过了头变成苦。<strong>苦节「贞凶」——即使守正也凶</strong>，因为强迫出来的节制走不远（道穷）。但「悔亡」——知道苦了，肯回头，悔恨就能消亡。</p><blockquote><p>两种极端（放纵 / 苦熬）只要知道了都能回来。知道苦，就是「悔」的开始；悔了，亡的是苦，不是节。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',25)),n(d,{title:"字词释义",items:[{term:"节",pinyin:["jié"],meaning:"竹节、节度、节制。竹子的节是自然长出来的刻度，不是外力捆上去的。"},{term:"苦节",pinyin:["kǔ","jié"],meaning:"苦苦硬撑、勉强压抑的节制。苦节不可贞——强迫出来的节制走不远。"},{term:"安节",pinyin:["ān","jié"],meaning:"安然而受、不费力的节制。安节是接上的，不是撑出来的。"},{term:"甘节",pinyin:["gān","jié"],meaning:"甘之如饴、发自内心喜悦的节制。甘节之吉，居中得正。"},{term:"户庭",pinyin:["hù","tíng"],meaning:"户为内门，庭为堂前院子；家门以内。「不出户庭」即连内门都不出。"},{term:"门庭",pinyin:["mén","tíng"],meaning:"门为大门；门庭即家门口，家门内外之交。「不出门庭」已到门口却不出。"},{term:"若",pinyin:["ruò"],meaning:"语助词，「……的样子」。「不节若」即不节制的样子。"},{term:"嗟",pinyin:["jiē"],meaning:"叹息、嗟叹。「嗟若」即嗟叹的样子。那一声叹气，就是六三的全部。"},{term:"知通塞",pinyin:["zhī","tōng","sè"],meaning:"知道通与不通，判断时机的开合。初九不出户庭，正是知通塞。"},{term:"失时极",pinyin:["shī","shí","jí"],meaning:"错过时机的极点。九二时机已到却不出，失时到了极点。"},{term:"承上道",pinyin:["chéng","shàng","dào"],meaning:"承顺上面的道。六四顺承九五，安节因承上道而亨。"},{term:"制数度",pinyin:["zhì","shù","dù"],meaning:"制定数量与法度。数度是节的外形，把分寸定下来。"},{term:"议德行",pinyin:["yì","dé","xíng"],meaning:"斟酌、讲求德行。从外在数度回到内心自觉。"},{term:"悔亡"}]}),t[2]||(t[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>节卦上坎（水、险）下兑（泽、悦）——泽上有水。水入泽，泽承而不溢，正是「节」之象。</p><p>卦辞「节，亨。苦节不可贞」点明：节是亨通的，但苦节不可持久。</p><p>核心意象<strong>泽承水</strong>：节不是不让水进来，是泽有足够容量承住水。先承住，才知道节在哪里。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>节，不是外部规则，是内心的数度。</p><p>三种节递进：</p><ul><li><strong>苦节</strong>（上六）——咬牙强迫，道穷；强迫出来的节制走不远</li><li><strong>安节</strong>（六四）——安然承受，承上道；接上的，不是撑出来的</li><li><strong>甘节</strong>（九五）——发自内心喜悦，居中正；把节活成喜欢的样子</li></ul><p>度不是靠控，是靠觉——知道自己有多少容量，节就长在哪。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>先承住再谈节：别急着堵水，先看自己这个泽容量够不够</li><li>每件事单独判断它的节点（初九知通塞）：通的走，塞的停</li><li>该出时出（九二教训）：时机到了不出，是另一种失节</li><li>失节了先认（六三嗟若）：那一声叹气就是回头的开始</li><li>把节活成甘（九五）：发自内心喜欢这样活，节才走得远</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>节卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>节亨，苦节不可贞</td><td>节是亨通的，苦节走不远</td><td>内心的数度</td></tr><tr><td>初九</td><td>不出户庭，无咎</td><td>知通塞，每件事单独判断节点</td><td>主动的度</td></tr><tr><td>九二</td><td>不出门庭，凶</td><td>时机到了不出，是另一种失节</td><td>失时极</td></tr><tr><td>六三</td><td>不节若，则嗟若，无咎</td><td>失节了认了，那声嗟叹就是全部</td><td>认，就无咎</td></tr><tr><td>六四</td><td>安节，亨</td><td>接上的，不是撑出来的</td><td>承上道</td></tr><tr><td>九五</td><td>甘节，吉，往有尚</td><td>发自内心喜欢这样活</td><td>居中正</td></tr><tr><td>上六</td><td>苦节，贞凶，悔亡</td><td>知道苦了就能回来</td><td>道穷则悔</td></tr></tbody></table><p>三种节的阶梯：</p><table tabindex="0"><thead><tr><th>节</th><th>状态</th><th>关键</th><th>出处</th></tr></thead><tbody><tr><td>苦节</td><td>咬牙强迫</td><td>道穷，走不远</td><td>上六</td></tr><tr><td>安节</td><td>安然承受</td><td>承上道，接上了</td><td>六四</td></tr><tr><td>甘节</td><td>发自内心</td><td>居中正，乐在其中</td><td>九五</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>节不是外部规则，是内心的数度</strong></li><li><strong>泽承水</strong>——先承住才知道节在哪，节是容量不是闸门</li><li><strong>苦节不可贞</strong>——强迫出来的节制走不远</li><li><strong>知通塞</strong>——每件事单独判断它的节点</li><li><strong>时机到了不出是另一种失节</strong></li><li><strong>那一声嗟叹就是六三的全部</strong>——认了，节才接得回来</li><li><strong>安节是接上的，不是撑出来的</strong></li><li><strong>甘节原型</strong>——把节活成喜欢的样子</li><li><strong>苦节贞凶悔亡</strong>——知道苦了，就能回来</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><ul><li><strong>竹节 × dao-commit</strong>：每次 commit 就是一节。竹子的节不是被捆出来的，是长出来的——dao-commit 的节，是自己愿意写进历史的刻度。</li><li><strong>说以行险</strong>：带着喜悦走险路。节不是苦行，是「说」（悦）着行——下兑的悦托着上坎的险，节才走得动。</li><li><strong>能控制的定死，不能控制的留弹性</strong>：数度定在能控处（日程、预算、commit 纪律），弹性留给不能控处（结果、时运、他人）。</li><li><strong>甘节原型</strong>：DOTA 攻略、北京剪辑、婚礼视频——不是黑历史，是甘节原型。那些当年心甘情愿、乐在其中的投入，就是甘节的活样本。回头看看自己甘过什么，就知道节该长在哪。</li><li><strong>三种节的位置</strong>：苦节是憋出来的，安节是接上的，甘节是长出来的。我要的节，是长出来的那种。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：涣（第五十九卦）、中孚（第六十一卦）</li><li>涣节相对：涣是散、节是聚；涣是打开、节是收拢。把散的收回来就是节，把节的放开就是涣。节卦从涣卦而来——散了才需要节，节了才能不散。</li><li>中孚之信：节以制度之外，还要以中孚立信。内里信实，外在的节才有根；节而无信，就成了苦节。</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',23))])}}});export{x as __pageData,b as default};
